script:
frappe.ui.form.on("Trip", {
	setup(frm) {
		frm.set_query("vehicle", () => ({
			filters: { status: ["not in", ["Inactive", "Maintenance"]] }
		}));
		frm.set_query("driver", () => ({ filters: { status: "Active" } }));
		frm.set_query("origin", () => ({ filters: { is_active: 1 } }));
		frm.set_query("destination", () => ({ filters: { is_active: 1 } }));
	},

	refresh(frm) {
		frm.dashboard.clear_headline_alert();
		if (!frm.is_new()) {
			frm.trigger("render_status_banner");
			frm.trigger("render_custom_buttons");
		}
		frm.trigger("calculate_total_expenses");
	},

	render_status_banner(frm) {
		const color_map = {
			"Draft": "grey",
			"Pending Approval": "orange",
			"Approved": "blue",
			"In Progress": "cyan",
			"Completed": "green",
			"Rejected": "red",
			"Cancelled": "darkgrey"
		};
		if (frm.doc.status) {
			frm.dashboard.set_headline_alert(__("Trip Status: <b>{0}</b>", [frm.doc.status]), color_map[frm.doc.status] || "blue");
		}
	},

	render_custom_buttons(frm) {
		const status = frm.doc.status;
		if (status === "Draft") {
			frm.add_custom_button(__("Submit for Approval"), () => {
				frappe.confirm(__("Submit trip for approval?"), () => {
					frm.set_value("status", "Pending Approval");
					frm.save();
				});
			}, __("Workflow")).addClass("btn-primary");
		}
		if (status === "Pending Approval") {
			frm.add_custom_button(__("Approve Trip"), () => {
				frm.set_value("status", "Approved");
				frm.save();
			}, __("Workflow")).addClass("btn-success");
			frm.add_custom_button(__("Reject Trip"), () => {
				frappe.prompt([{ fieldname: "reason", fieldtype: "Small Text", label: __("Rejection Reason"), reqd: 1 }], (vals) => {
					frm.set_value("remarks", (frm.doc.remarks ? frm.doc.remarks + "\n" : "") + "Rejection reason: " + vals.reason);
					frm.set_value("status", "Rejected");
					frm.save();
				}, __("Reject Trip"));
			}, __("Workflow")).addClass("btn-danger");
		}
		if (status === "Approved") {
			frm.add_custom_button(__("Dispatch Vehicle"), () => {
				frappe.prompt([
					{ fieldname: "actual_start", fieldtype: "Datetime", label: __("Actual Start Time"), default: frappe.datetime.now_datetime(), reqd: 1 },
					{ fieldname: "opening_odometer", fieldtype: "Float", label: __("Opening Odometer (km)"), default: frm.doc.opening_odometer || 0, reqd: 1 }
				], (vals) => {
					frm.set_value("status", "In Progress");
					frm.set_value("actual_start", vals.actual_start);
					frm.set_value("opening_odometer", vals.opening_odometer);
					frm.save();
				}, __("Dispatch Vehicle"));
			}, __("Actions")).addClass("btn-primary");
		}
		if (status === "In Progress") {
			frm.add_custom_button(__("Complete Trip"), () => {
				frappe.prompt([
					{ fieldname: "actual_end", fieldtype: "Datetime", label: __("Actual End Time"), default: frappe.datetime.now_datetime(), reqd: 1 },
					{ fieldname: "closing_odometer", fieldtype: "Float", label: __("Closing Odometer (km)"), default: frm.doc.opening_odometer || 0, reqd: 1 }
				], (vals) => {
					if (flt(vals.closing_odometer) < flt(frm.doc.opening_odometer)) {
						frappe.msgprint(__("Closing odometer cannot be less than opening odometer ({0} km).", [frm.doc.opening_odometer]));
						return;
					}
					frm.set_value("status", "Completed");
					frm.set_value("actual_end", vals.actual_end);
					frm.set_value("closing_odometer", vals.closing_odometer);
					frm.trigger("calculate_distance");
					frm.save();
				}, __("Complete Trip"));
			}, __("Actions")).addClass("btn-success");
		}
	},

	opening_odometer(frm) { frm.trigger("calculate_distance"); },
	closing_odometer(frm) { frm.trigger("calculate_distance"); },
	calculate_distance(frm) {
		if (frm.doc.opening_odometer != null && frm.doc.closing_odometer != null) {
			const diff = flt(frm.doc.closing_odometer) - flt(frm.doc.opening_odometer);
			frm.set_value("distance_travelled", diff >= 0 ? diff : 0);
		}
	},
	calculate_total_expenses(frm) {
		let total = 0;
		(frm.doc.trip_expenses || []).forEach((row) => { total += flt(row.amount); });
		if (total > 0 && !frm.is_new()) {
			frm.dashboard.set_headline_alert(__("Total Trip Expenses: <b>{0}</b>", [format_currency(total)]), "blue");
		}
	}
});

frappe.ui.form.on("Vehicle", {
	refresh(frm) {
		frm.dashboard.clear_headline_alert();
		if (frm.is_new()) return;

		const alerts = {
			"Available": { msg: __("Vehicle is Available for dispatch"), color: "green" },
			"On Trip": { msg: __("Vehicle is currently On Trip"), color: "blue" },
			"Maintenance": { msg: __("Vehicle is under Maintenance"), color: "orange" },
			"Inactive": { msg: __("Vehicle is Inactive"), color: "red" }
		};
		if (frm.doc.status && alerts[frm.doc.status]) {
			frm.dashboard.set_headline_alert(alerts[frm.doc.status].msg, alerts[frm.doc.status].color);
		}
		if (frm.doc.status === "Available") {
			frm.add_custom_button(__("Create Trip"), () => {
				frappe.new_doc("Trip", { vehicle: frm.doc.name, opening_odometer: frm.doc.current_odometer || 0 });
			}, __("Actions"));
		}
		frm.add_custom_button(__("View Trips"), () => {
				frappe.set_route("List", "Trip", { vehicle: frm.doc.name });
			}, __("Navigation"));
	},

	registration_number(frm) {
		if (frm.doc.registration_number) {
			frm.set_value("registration_number", frm.doc.registration_number.toUpperCase().trim());
		}
	}
});

frappe.ui.form.on("Driver", {
	refresh(frm) {
		frm.dashboard.clear_headline_alert();
		if (frm.is_new()) return;

		if (frm.doc.status) {
			const colors = { "Active": "green", "Inactive": "red", "Suspended": "orange" };
			frm.dashboard.set_headline_alert(__("Driver Status: <b>{0}</b>", [frm.doc.status]), colors[frm.doc.status] || "blue");
		}
		if (frm.doc.license_expiry_date) {
			const days = frappe.datetime.get_diff(frm.doc.license_expiry_date, frappe.datetime.get_today());
			if (days < 0) {
				frm.dashboard.set_headline_alert(__("Driver Licence is EXPIRED ({0} days ago)", [Math.abs(days)]), "red");
			} else if (days <= 30) {
				frm.dashboard.set_headline_alert(__("Driver Licence expires soon (in {0} days)", [days]), "orange");
			}
		}
		if (frm.doc.status === "Active") {
			frm.add_custom_button(__("Create Trip"), () => {
				frappe.new_doc("Trip", { driver: frm.doc.name });
			}, __("Actions"));
		}
		frm.add_custom_button(__("View Assigned Trips"), () => {
				frappe.set_route("List", "Trip", { driver: frm.doc.name });
			}, __("Navigation"));
	},

	license_expiry_date(frm) {
		if (frm.doc.license_expiry_date) {
			const days = frappe.datetime.get_diff(frm.doc.license_expiry_date, frappe.datetime.get_today());
			if (days < 0) {
				frappe.msgprint({ title: __("Licence Expired"), indicator: "red", message: __("The licence expiry date is in the past ({0}).", [frm.doc.license_expiry_date]) });
			} else if (days <= 30) {
				frappe.show_alert({ message: __("Warning: Licence expires soon in {0} days.", [days]), indicator: "orange" });
			}
		}
	},

	license_number(frm) {
		if (frm.doc.license_number) {
			frm.set_value("license_number", frm.doc.license_number.toUpperCase().trim());
		}
	}
});

frappe.ui.form.on("Maintenance Request", {
	refresh(frm) {
		frm.dashboard.clear_headline_alert();
		if (frm.is_new()) return;

		if (frm.doc.status) {
			const colors = { "Open": "orange", "In Progress": "blue", "Completed": "green", "Cancelled": "grey" };
			frm.dashboard.set_headline_alert(__("Status: <b>{0}</b> (Priority: {1})", [frm.doc.status, frm.doc.priority || "Medium"]), colors[frm.doc.status] || "blue");
		}
		if (frm.doc.status === "Open" || frm.doc.status === "In Progress") {
			frm.add_custom_button(__("Complete Maintenance"), () => {
				frappe.prompt([
					{ fieldname: "resolution_notes", fieldtype: "Text", label: __("Resolution Notes"), reqd: 1, default: frm.doc.resolution_notes || "" },
					{ fieldname: "cost", fieldtype: "Currency", label: __("Total Cost"), default: frm.doc.cost || 0 }
				], (vals) => {
					frm.set_value("status", "Completed");
					frm.set_value("resolution_notes", vals.resolution_notes);
					frm.set_value("cost", vals.cost);
					frm.save();
				}, __("Complete Maintenance"));
			}, __("Actions")).addClass("btn-success");
		}
	}
});

frappe.ui.form.on("Fleet Location", {
	refresh(frm) {
		frm.dashboard.clear_headline_alert();
		if (frm.is_new()) return;

		if (!frm.doc.is_active) {
			frm.dashboard.set_headline_alert(__("Location is Inactive"), "red");
		} else {
			frm.dashboard.set_headline_alert(__("Location is Active"), "green");
		}
	}
});
